"""Home reference composition; reuse existing trip, navigation and map contracts."""

def render(p,g):
 a,image,icon,url,ext=[g[k] for k in ['a','image','icon','url','ext']]
 hotels=g['HOTELS']
 def form(bottom=False):
  s=g['booking_form'](bottom=bottom)
  for label,ic in [('Отель','pin'),('Даты поездки','calendar'),('Гости','guest')]:
   s=s.replace('>'+label+'<', '><span class="home-field-icon">'+icon(ic)+'</span><span class="home-field-label">'+('Заезд — Выезд' if label=='Даты поездки' else label)+'</span><')
  return s
 slides='';slide_buttons=''
 for n,(i,h) in enumerate(hotels.items(),1):
  active=n==1
  slides+='<div class="hero-slide'+(' is-active' if active else '')+'" id="hero-slide-'+i+'" data-hero-slide="'+i+'" role="group" aria-roledescription="слайд" aria-label="'+str(n)+' из 4: '+h['full']+'"'+('' if active else ' aria-hidden="true" inert')+'>'+image(i,'Фасад отеля '+h['full'],eager=active)+'<div class="hero-slide-caption"><span>'+h['location']+'</span>'+a(i,h['full']+' '+icon('arrow'),'hero-hotel-link')+'</div></div>'
  slide_buttons+='<button type="button" data-hero-pick="'+str(n-1)+'" aria-controls="hero-slide-'+i+'" aria-label="Показать отель '+h['name']+'" aria-pressed="'+str(active).lower()+'"><span class="hero-slide-number">0'+str(n)+'</span><span class="hero-slide-name">'+h['name']+'</span><span class="hero-slide-progress" aria-hidden="true"></span></button>'
 slider='<div class="hero-visual home-hero-photo hero-carousel" data-hero-carousel role="region" aria-roledescription="карусель" aria-label="Четыре отеля Туррис в Москве">'+slides+'<div class="hero-carousel-controls"><div class="hero-slide-picker" aria-label="Выбор отеля">'+slide_buttons+'</div><div class="hero-carousel-actions"><button type="button" data-hero-prev aria-label="Предыдущий отель">'+icon('arrow')+'</button><button type="button" data-hero-play aria-label="Остановить автоматическую смену отелей"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path class="slider-pause-icon" d="M8 5v14M16 5v14"/><path class="slider-play-icon" d="m9 5 10 7-10 7Z"/></svg></button><button type="button" data-hero-next aria-label="Следующий отель">'+icon('arrow')+'</button></div></div><span class="hero-slider-status" role="status" aria-live="polite" aria-atomic="true"></span></div>'
 mobile_map='<div class="home-mobile-map" data-mobile-map-slot><h2>Выберите свой адрес</h2><p class="mobile-map-intro">Нажмите на отметку или название отеля.</p></div>'
 hero='<section class="hero home-hero"><div class="hero-copy"><h1>Отели Туррис в центре Москвы</h1><p class="sub">Четыре адреса для отдыха и деловых поездок. Выберите расположение и номер на ваши даты.</p></div>'+slider+mobile_map+'<div class="home-booking" id="home-search" aria-label="Поиск номера">'+form()+'<div class="home-search-caption"><p>Стоимость, питание и отмена — в выбранном тарифе.</p><a href="tel:88005054455">Поможем выбрать: 8 800 505 44 55</a></div></div></section>'
 map_markup=g['maplinks']().replace('<p class="map-footnote">','<div class="home-map-compare">'+a('hotels','Сравнить условия отелей '+icon('arrow'),'text-link')+'</div><p class="map-footnote">')
 hotel_map='<section class="section home-map-section" id="hotels"><div class="section-heading"><div><h2>Найдите свой адрес в Москве</h2><p class="sub">Выберите отель на карте: адрес, условия и номера — в карточке.</p></div></div>'+map_markup+'</section>'
 direct='<section class="section home-direct"><h2>Понятное бронирование</h2>'+g['benefits']()+'<div class="center-link">'+a('loyalty','Программа «Туррис-Бонус» '+icon('arrow'),'text-link')+'</div></section>'
 offers='<div class="home-offers"><section class="section-sm"><div class="feature"><div class="feature-media">'+image('tverskaya_room_1','Спальня семейного люкса Тверской',sizes='(max-width:640px) calc(100vw - 32px), 350px')+'</div><div class="feature-copy"><div class="eyebrow">Тверская · семейный люкс</div><h2>Вместе — и с местом для каждого</h2><p>Спальня с большой кроватью и гостиная с диваном.<br>Вместимость до 4 мест.</p>'+a('family','Подобрать семейный номер '+icon('arrow'),'btn secondary')+a('family','Все варианты для семьи '+icon('arrow'),'text-link')+'</div></div></section><section class="section-sm"><div class="feature pale"><div class="feature-media">'+image('petrovsky','Фасад отеля Туррис Петровский',sizes='400px')+'</div><div class="feature-copy"><div class="eyebrow">Петровский · от 21 дня</div><h2>Останьтесь в Москве подольше</h2><p>Для проектной работы или переезда.</p>'+a('longstay','Узнать условия '+icon('arrow'),'btn secondary')+'</div></div></section></div>'
 review='<section class="home-review"><h2>Гости о своём проживании</h2><div class="quote"><div class="quote-mark" aria-hidden="true">“</div><div><blockquote><p>В номере чисто, всё необходимое есть. Персонал внимательный и вежливый.</p></blockquote><span class="small">Татьяна Н. · Тверская · фрагмент отзыва на Путёвка.ком</span></div>'+ext('https://www.putevka.com/moskva/moskva/turris-tverskaya','Читать полный отзыв')+'</div></section>'
 team='<section class="team-band home-team">'+icon('guest')+'<div><h2>Разместим вашу команду</h2><p>Для компаний и организаторов групп. Для расчёта свяжитесь с отделом бронирования. Форма запроса пока работает в демонстрационном режиме.</p></div><div class="team-action">'+a('groups','Запросить расчёт '+icon('arrow'),'btn white')+a('business','Условия для компаний ↗','text-link')+'</div></section>'
 faq='<section class="section home-faq"><div><h2>Перед бронированием</h2><p>Ответим на вопросы о вашей поездке.</p><a href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a></div>'+g['faqs'](opened=False)+'</section>'
 bottom='<section class="booking-bottom"><h2>Ваша поездка начинается с дат</h2><p class="sub">Выберите расположение и посмотрите номера на время поездки.</p>'+form(True)+'<p class="help-line">Поможем с выбором. <a href="tel:88005054455">8 800 505 44 55</a></p></section>'
 mobile_actions='<nav class="home-mobile-actions" aria-label="Быстрый выбор номера" hidden><button type="button" data-mobile-map>'+icon('pin')+'<span>Карта отелей</span></button><button type="button" class="btn" data-mobile-book>Выбрать даты '+icon('arrow')+'</button></nav>'
 return '<div class="wrap home-page">'+hero+hotel_map+direct+offers+review+team+faq+bottom+'</div>'+mobile_actions
